import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;

public class Main {
    @FunctionalInterface
    interface MathOp {
        int apply(int a, int b);
        default String name() { return "math"; }
        static MathOp plus() { return (a, b) -> a + b; }
    }

    void run() {
        MathOp add = MathOp.plus();
        MathOp multiply = (a, b) -> a * b;
        Predicate<String> nonEmpty = s -> !s.isEmpty();
        Function<String, Integer> length = String::length;
        Supplier<List<String>> factory = ArrayList::new;

        List<String> names = factory.get();
        names.addAll(List.of("Bob", "Alice", "Charlie"));
        names.sort(Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));
        List<String> upper = names.stream().filter(nonEmpty).map(String::toUpperCase).collect(Collectors.toList());

        String prefix = "hi ";
        Function<String, String> greeter = name -> prefix + name;
        Object lambdaThis = ((Supplier<Object>) () -> this).get();
        Object anonymousThis = new Supplier<Object>() {
            public Object get() { return this; }
        }.get();

        System.out.println("sum: " + add.apply(3, 5));
        System.out.println("multiply: " + multiply.apply(3, 5));
        System.out.println("length(Alice): " + length.apply("Alice"));
        System.out.println("sorted: " + names);
        System.out.println("upper: " + upper);
        System.out.println("captured: " + greeter.apply("lambda"));
        System.out.println("lambda this is outer: " + (lambdaThis == this));
        System.out.println("anonymous this is outer: " + (anonymousThis == this));

        assert add.apply(3, 5) == 8;
        assert add.name().equals("math");
        assert multiply.apply(3, 5) == 15;
        assert upper.equals(List.of("BOB", "ALICE", "CHARLIE"));
        assert greeter.apply("lambda").equals("hi lambda");
        assert lambdaThis == this;
        assert anonymousThis != this;
    }

    public static void main(String[] args) {
        new Main().run();
    }
}
